import java.io.*;

public class Main {
    static boolean reaches(long n, long a, long limit) {
        if (n > (limit - 1) / a) return true;

        long base = n * a;
        long remaining = limit - base;

        long x = n;
        long y = n - 1;
        if ((x & 1) == 0) x /= 2;
        else y /= 2;

        return y != 0 && x > (remaining - 1) / y;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int p = (int) fs.nextLong();
        StringBuilder out = new StringBuilder();

        for (int i = 0; i < p; i++) {
            long l = fs.nextLong();
            long a = fs.nextLong();
            long b = fs.nextLong();
            long count = b - a + 1;

            long answer;
            if (!reaches(count, a, l)) {
                answer = count;
            } else {
                long low = 1;
                long high = count;
                while (low < high) {
                    long mid = low + (high - low) / 2;
                    if (reaches(mid, a, l)) high = mid;
                    else low = mid + 1;
                }
                answer = low;
            }

            out.append(answer).append('\n');
        }

        System.out.print(out);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream in) {
            this.in = in;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            long value = 0;
            while (c > ' ') {
                value = value * 10 + (c - '0');
                c = read();
            }
            return value;
        }
    }
}
